// Typedef for function signature clarity: int(void*, void*)
typedef int (*Comparator)(const void*, const void*);

// Structure holding the function pointer (the Callback Context)
typedef struct {
    int event_id;
    Comparator handler_fn;
    void* user_data;
} EventHandler;

// Implementation function matching the signature
int context_compare(const void* a, const void* b) {
    return (*(int*)a - *(int*)b);
}

// Function that invokes the callback
void run_handler(EventHandler* eh, int item_value) {
    int current_val = *(int*)eh->user_data;
    if (eh->handler_fn(&current_val, &item_value) > 0) { /* Process */ }
}

// Initialization of the complex pointer mechanism
int state = 100;
EventHandler registration = {
    .event_id = 5,
    .handler_fn = context_compare,
    .user_data = &state
};

// Invocation: run_handler(&registration, 50);
